function cpPresets(){
  return {
    triangle:[[50,0],[0,100],[100,100]],
    arrow:[[0,20],[60,20],[60,0],[100,50],[60,100],[60,80],[0,80]],
    star:[[50,0],[61,35],[98,35],[68,57],[79,91],[50,70],[21,91],[32,57],[2,35],[39,35]],
    hexagon:[[25,0],[75,0],[100,50],[75,100],[25,100],[0,50]],
    message:[[0,0],[100,0],[100,75],[75,75],[75,100],[50,75],[0,75]]
  };
}
function cpClamp(v){ var x=Number(v); if(!isFinite(x)) x=0; return Math.min(100,Math.max(0,Math.round(x*100)/100)); }
function cpToCss(pts){
  if(!pts || pts.length<3) return '';
  return 'polygon('+pts.map(function(p){ return cpClamp(p[0])+'% '+cpClamp(p[1])+'%'; }).join(', ')+')';
}
function cpParse(css){
  var m=/polygon\(([^)]*)\)/.exec(String(css||''));
  if(!m) return null;
  var pts=m[1].split(',').map(function(seg){
    var mm=/([\d.]+)%\s+([\d.]+)%/.exec(seg.trim());
    return mm ? [Number(mm[1]),Number(mm[2])] : null;
  });
  if(pts.indexOf(null)>=0 || pts.length<3) return null;
  return pts;
}
function cpMidInsert(pts, i){
  if(!pts || pts.length<3) return pts;
  var a=pts[i%pts.length], b=pts[(i+1)%pts.length];
  var mid=[cpClamp((a[0]+b[0])/2), cpClamp((a[1]+b[1])/2)];
  var out=pts.slice(0,i+1); out.push(mid); return out.concat(pts.slice(i+1));
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { cpPresets:cpPresets, cpClamp:cpClamp, cpToCss:cpToCss, cpParse:cpParse, cpMidInsert:cpMidInsert };
}
if (typeof window !== 'undefined') {
  window.ClipForgePure = { cpPresets:cpPresets, cpClamp:cpClamp, cpToCss:cpToCss, cpParse:cpParse, cpMidInsert:cpMidInsert };
}
